+.cookie p{margin:0;color:var(--muted);font-size:13px;max-width:78ch}
+.cookie-actions{display:flex;gap:10px;flex-wrap:wrap}
+
+.kicker{
+  display:flex;gap:10px;align-items:center;color:var(--muted);font-size:13px
+}
