+.page-title h1{font-size:36px;margin:8px 0 6px}
+.page-title p{margin:0;color:var(--muted);max-width:78ch}
+
+.two-col{display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:start}
+
+@media (max-width: 980px){
+  h1{font-size:38px}
+  .hero-grid{grid-template-columns:1fr}
+  .grid-3{grid-template-columns:1fr 1fr}
+  .grid-4{grid-template-columns:1fr 1fr}
+  .stats{grid-template-columns:1fr}
+  .timeline-item{grid-template-columns:1fr}
+  .footer-grid{grid-template-columns:1fr}
+  .cookie-inner{flex-direction:column}
+  .two-col{grid-template-columns:1fr}
+}
+
+@media (max-width: 640px){
+  :root{--gutter:16px;--header-h:66px}
+  h1{font-size:32px}
+  .nav{display:none}
+  .fields{grid-template-columns:1fr}
+  .grid-3{grid-template-columns:1fr}
+  .grid-2{grid-template-columns:1fr}
+  .ecosystem{grid-template-columns:1fr}
+  .ecosystem svg{display:none}
+}
+
+@media (prefers-reduced-motion: reduce){
+  html{scroll-behavior:auto}
+  .btn,.tab,.carousel-track{transition:none}
+}
+
